import type { CoachProfile } from '../features/coachAgent/recommendation/types'
import { ROUTINE_SESSION_STORAGE_KEY } from '../features/routines/session/RoutineSessionRepository'
import { SESSION_STORAGE_KEY } from '../features/training/LocalStorageTrainingSessionRepository'
import { FULL_IMPROVEMENT, at } from '../../tests/analysis-fixtures'
import { routineRecord } from '../../tests/helpers/routineFixtures'

/**
 * SYNTHETIC DEMO DATASET for the public AI Coach demo — a fictional user, generated by program, not a real person.
 *
 * The records are the same test fixtures the V1.2 agent evaluation used (tests/llm-eval/fixtures.ts): two warm-up
 * sessions whose every score comes from the real scoring functions, and two 八段锦 follow-along records. They are kept in
 * memory only (never written to the visitor's localStorage) and every tool result and evidence row that reads them
 * carries DEMO_DATASET_NOTE.
 */
export const DEMO_DATASET_NOTE = '合成示例记录：虚构的示例用户，由程序生成，不是访问者本人的训练数据'

export const DEMO_PROFILE: CoachProfile = { version: 1, goals: ['mobility'], difficulties: ['stiffness'], regions: ['shoulders', 'neck'], preference: 'mixed', risk: 'none', acknowledged: true }

const WARMUP = [...FULL_IMPROVEMENT.history, FULL_IMPROVEMENT.current].map((session) => ({ ...session, id: `demo-${session.id}` }))
const ROUTINE = [
  routineRecord({ id: 'demo-bdj-1', startedAt: at(3), chapters: { 'bdj-5': { similarity: 0.6 } } }),
  routineRecord({ id: 'demo-bdj-2', startedAt: at(5), chapters: { 'bdj-2': { similarity: 0.62 }, 'bdj-5': { similarity: 0.58 } } }),
]

/** Read-only, in-memory storage holding only the synthetic records. */
export function createDemoStorage(): Pick<Storage, 'getItem'> {
  const map = new Map<string, string>([[SESSION_STORAGE_KEY, JSON.stringify(WARMUP)], [ROUTINE_SESSION_STORAGE_KEY, JSON.stringify(ROUTINE)]])
  return { getItem: (key: string) => map.get(key) ?? null }
}
